--- /dev/null	2026-09-10 18:39:31
+++ /tmp/lazy-appium-url/packages/base-driver/test/unit/protocol/validators.spec.ts	2026-09-10 18:30:45
@@ -0,0 +1,32 @@
+import assert from 'node:assert/strict';
+import {describe, it} from 'node:test';
+
+import {validators} from '../../../lib/protocol/validators';
+
+describe('protocol validators', function () {
+  describe('#setUrl', function () {
+    it('should preserve supported URL forms', function () {
+      for (const url of ['http://example.com', 'about:blank', 'data:text/plain,hi', 'ftp://example.com']) {
+        assert.doesNotThrow(() => validators.setUrl(url));
+      }
+    });
+
+    it('should reject non-string values without throwing a TypeError', function () {
+      for (const url of [123, true, {}, [], null, undefined]) {
+        assert.throws(
+          () => validators.setUrl(url),
+          (error: unknown) => {
+            assert.ok(error instanceof Error);
+            assert.notEqual(error.name, 'TypeError');
+            return true;
+          },
+        );
+      }
+    });
+
+    it('should reject empty and relative strings', function () {
+      assert.throws(() => validators.setUrl(''));
+      assert.throws(() => validators.setUrl('example.com'));
+    });
+  });
+});

