--- /dev/null	2026-09-10 18:39:31
+++ /tmp/lazy-appium-cli/packages/appium/test/unit/schema/cli-transformers.spec.ts	2026-09-10 18:35:24
@@ -0,0 +1,42 @@
+import assert from 'node:assert/strict';
+import {mkdirSync, mkdtempSync, rmSync, writeFileSync} from 'node:fs';
+import os from 'node:os';
+import path from 'node:path';
+import {after, before, describe, it} from 'node:test';
+
+import {transformers} from '../../../lib/schema/cli-transformers';
+
+describe('CLI transformers', function () {
+  let tmpDir: string;
+
+  before(function () {
+    tmpDir = mkdtempSync(path.join(os.tmpdir(), 'appium-cli-transformers-'));
+  });
+
+  after(function () {
+    rmSync(tmpDir, {recursive: true, force: true});
+  });
+
+  it('should treat an existing directory as a CSV value', function () {
+    const directory = path.join(tmpDir, 'feature');
+    mkdirSync(directory);
+    assert.deepStrictEqual(transformers.csv(directory), [directory]);
+  });
+
+  it('should still load a CSV file', function () {
+    const file = path.join(tmpDir, 'features.csv');
+    writeFileSync(file, 'adb_shell\nget_server_logs\n', 'utf8');
+    assert.deepStrictEqual(transformers.csv(file), ['adb_shell', 'get_server_logs']);
+  });
+
+  it('should treat an existing directory as a JSON value', function () {
+    const directory = path.join(tmpDir, 'caps');
+    mkdirSync(directory);
+    assert.throws(() => transformers.json(directory), /must be a valid JSON/i);
+  });
+
+  it('should parse long inline JSON values', function () {
+    const caps = {'appium:app': 'a'.repeat(300)};
+    assert.deepStrictEqual(transformers.json(JSON.stringify(caps)), caps);
+  });
+});

