--- /dev/null	2026-09-10 18:51:22
+++ /tmp/lazy-appium-cli/packages/appium/test/unit/schema/cli-transformers.spec.ts	2026-09-10 18:50:52
@@ -0,0 +1,81 @@
+import assert from 'node:assert/strict';
+import {mkdirSync, mkdtempSync, rmSync, writeFileSync} from 'node:fs';
+import os from 'node:os';
+import path from 'node:path';
+import {after, before, describe, it} from 'node:test';
+
+import {transformers} from '../../../lib/schema/cli-transformers';
+
+describe('CLI transformers', function () {
+  let tmpDir: string;
+
+  before(function () {
+    tmpDir = mkdtempSync(path.join(os.tmpdir(), 'appium-cli-transformers-'));
+  });
+
+  after(function () {
+    rmSync(tmpDir, {recursive: true, force: true});
+  });
+
+  it('should treat an existing directory as a CSV value', function () {
+    const directory = path.join(tmpDir, 'feature');
+    mkdirSync(directory);
+    assert.deepStrictEqual(transformers.csv(directory), [directory]);
+  });
+
+  it('should still load a CSV file', function () {
+    const file = path.join(tmpDir, 'features.csv');
+    writeFileSync(file, 'adb_shell\nget_server_logs\n', 'utf8');
+    assert.deepStrictEqual(transformers.csv(file), ['adb_shell', 'get_server_logs']);
+  });
+
+  it('should parse long inline CSV values when stat reports a path error', function () {
+    const csv = Array.from({length: 64}, (_, index) => `feature${index}`).join(',');
+    assert.ok(csv.length > 255);
+    assert.deepStrictEqual(transformers.csv(csv), csv.split(','));
+  });
+
+  it('should treat an existing directory as a JSON value', function () {
+    const directory = path.join(tmpDir, 'caps');
+    mkdirSync(directory);
+    assert.throws(() => transformers.json(directory), /must be a valid JSON/i);
+  });
+
+  it('should parse long inline JSON values', function () {
+    const caps = {'appium:app': 'a'.repeat(300)};
+    assert.deepStrictEqual(transformers.json(JSON.stringify(caps)), caps);
+  });
+
+  it('should load a JSON file', function () {
+    const file = path.join(tmpDir, 'caps.json');
+    const caps = {foo: 1};
+    writeFileSync(file, JSON.stringify(caps), 'utf8');
+    assert.deepStrictEqual(transformers.json(file), caps);
+  });
+
+  it('should report malformed inline JSON with its parse cause', function () {
+    assert.throws(
+      () => transformers.json('{bad'),
+      (error: unknown) => {
+        assert.ok(error instanceof TypeError);
+        assert.match(error.message, /The provided value must be a valid JSON/);
+        assert.ok(error.cause instanceof SyntaxError);
+        return true;
+      },
+    );
+  });
+
+  it('should report malformed JSON files with their path and parse cause', function () {
+    const file = path.join(tmpDir, 'invalid.json');
+    writeFileSync(file, '{bad', 'utf8');
+    assert.throws(
+      () => transformers.json(file),
+      (error: unknown) => {
+        assert.ok(error instanceof TypeError);
+        assert.ok(error.message.includes(`'${file}' must be a valid JSON`));
+        assert.ok(error.cause instanceof SyntaxError);
+        return true;
+      },
+    );
+  });
+});

